}

.edu-wizard-root[data-theme="dark"] .edu-stepper-box,
.edu-wizard-root[data-theme="dark"] .edu-card-form,
[data-theme="dark"] .edu-stepper-box,
[data-theme="dark"] .edu-card-form {
  background: rgba(30, 41, 59, 0.7) !important;
