}

.edu-wizard-root[data-theme="dark"] .edu-input,
.edu-wizard-root[data-theme="dark"] .edu-select,
[data-theme="dark"] .edu-input,
[data-theme="dark"] .edu-select {
  background: #0f172a !important;
  border: 1.5px solid #334155 !important;
