}

.edu-wizard-root[data-theme="dark"] .edu-input:focus,
.edu-wizard-root[data-theme="dark"] .edu-select:focus,
[data-theme="dark"] .edu-input:focus,
[data-theme="dark"] .edu-select:focus {
