.edu-merit-formula code { background: rgba(0,0,0,0.06); padding: 3px 8px; border-radius: 6px; font-weight: 600; color: #475569; }
[data-theme="dark"] .edu-merit-formula code { background: rgba(255,255,255,0.1); color: #cbd5e1; }
.edu-merit-calc-val { display: flex; align-items: center; gap: 8px; font-size: 14.5px; color: #0f172a; }
[data-theme="dark"] .edu-merit-calc-val { color: #f8fafc; }
.edu-merit-calc-val strong { font-size: 20px; color: #6366f1; font-weight: 800; }
.edu-counsel-info-box {
