[data-theme="dark"] .edu-counsel-info-box p { color: #94a3b8; }
.edu-info-icon { font-size: 20px; line-height: 1; }
.edu-refresh-svg { vertical-align: middle; }

/* THEME SUPPORT & CRISP TYPOGRAPHY */
