  color: #64748b !important;
}
[data-theme="light"] .edu-review-line strong {
  color: #0f172a !important;
}

sp_widget.script:
(function() {
  data.isLoggedIn = gs.isLoggedIn();
  data.userName = gs.getUserDisplayName() || gs.getUserName();
  data.userInitial = data.userName ? data.userName.charAt(0).toUpperCase() : 'U';
  data.appNo = '';
  data.application = {};

  if (!data.isLoggedIn) return;

  var userEmail = gs.getUser().getEmail();
  var userName = gs.getUserName();

  function normalizeCategory(cat) {
    if (!cat) return 'general';
    cat = cat.toString().trim().toLowerCase().replace(/\s+/g, '_');
    if (cat === 'obc') return 'backward_class';
    if (cat === 'ews') return 'economically_weaker_section';
    if (cat === 'pwd') return 'person_with_disability';
    return cat;
  }

  // Existing Application Lookup
  var grApp = new GlideRecord('x_1790229_edusph_0_admission_application');
  var qc = grApp.addQuery('sys_created_by', userName);
  if (userEmail) {
    qc.addOrCondition('email', userEmail);
  }
  grApp.orderByDesc('sys_created_on');
  grApp.setLimit(1);
  grApp.query();
  if (grApp.next()) {
    data.appNo = grApp.getValue('app_no') || '';
    data.application = {
      sys_id: grApp.getUniqueValue(),
      name: grApp.getValue('name') || '',
      email: grApp.getValue('email') || userEmail,
      mobile: grApp.getValue('mobile') || '',
      date_of_birth: grApp.getValue('date_of_birth') || '',
      category: normalizeCategory(grApp.getValue('category')),
      class_10_percentage: parseFloat(grApp.getValue('class_10_percentage')) || '',
      class_12_percentage: parseFloat(grApp.getValue('class_12_percentage')) || '',
      jee_score: parseFloat(grApp.getValue('jee_score')) || '',
      status: grApp.getValue('status') || 'draft'
    };
  }

  // Save Draft Action
  if (input && input.action === 'save_draft') {
    try {
      var f = input.formData || {};
      var appGR = new GlideRecord('x_1790229_edusph_0_admission_application');
      var isExisting = false;

      if (f.sys_id && appGR.get(f.sys_id)) {
        isExisting = true;
      } else {
        var qcDraft = appGR.addQuery('sys_created_by', userName);
        if (userEmail) qcDraft.addOrCondition('email', userEmail);
        appGR.orderByDesc('sys_created_on');
        appGR.setLimit(1);
        appGR.query();
        if (appGR.next()) {
          isExisting = true;
        } else {
          appGR.initialize();
          appGR.setValue('status', 'draft');
          appGR.setValue('email', userEmail);
        }
      }

      var fields = ['name','email','mobile','date_of_birth','category','class_10_percentage','class_12_percentage','jee_score'];
      for (var i = 0; i < fields.length; i++) {
        var key = fields[i];
        if (f[key] !== undefined && f[key] !== '') {
          if (key === 'category') {
            appGR.setValue('category', normalizeCategory(f[key]));
          } else {
            appGR.setValue(key, f[key]);
          }
        }
      }

      var a10 = parseFloat(f.class_10_percentage) || 0;
      var a12 = parseFloat(f.class_12_percentage) || 0;
      var aJee = parseFloat(f.jee_score) || 0;
      if (a10 && a12 && aJee) {
        appGR.setValue('merit_score', ((a10 + a12 + aJee) / 3).toFixed(2));
      }

      var resId = isExisting ? appGR.update() : appGR.insert();
      if (resId) {
        appGR.get(resId);
        data.saved = true;
        data.appNo = appGR.getValue('app_no');
      }
    } catch (eDraft) {
      data.saved = false;
      data.errorMessage = eDraft.message;
    }
  }

  // Submit Application Action
  if (input && input.action === 'submit_application') {
    try {
      var s = input.formData || {};
      var subGR = new GlideRecord('x_1790229_edusph_0_admission_application');
      var isSubExisting = false;

      if (s.sys_id && subGR.get(s.sys_id)) {
        isSubExisting = true;
      } else {
        var qcSub = subGR.addQuery('sys_created_by', userName);
        if (userEmail) qcSub.addOrCondition('email', userEmail);
        subGR.orderByDesc('sys_created_on');
        subGR.setLimit(1);
        subGR.query();
        if (subGR.next()) {
          isSubExisting = true;
        } else {
          subGR.initialize();
          subGR.setValue('email', userEmail);
        }
      }

      var subFields = ['name','email','mobile','date_of_birth','category','class_10_percentage','class_12_percentage','jee_score'];
      for (var j = 0; j < subFields.length; j++) {
        var subKey = subFields[j];
        if (s[subKey] !== undefined && s[subKey] !== '') {
          if (subKey === 'category') {
            subGR.setValue('category', normalizeCategory(s[subKey]));
          } else {
            subGR.setValue(subKey, s[subKey]);
          }
        }
      }

      var s10 = parseFloat(s.class_10_percentage) || 0;
      var s12 = parseFloat(s.class_12_percentage) || 0;
      var sJee = parseFloat(s.jee_score) || 0;
      if (s10 && s12 && sJee) {
        subGR.setValue('merit_score', ((s10 + s12 + sJee) / 3).toFixed(2));
      }

      // Set initial status to submitted
      subGR.setValue('status', 'submitted');
      subGR.setValue('applied_on', new GlideDate().getValue());

      var subRes = isSubExisting ? subGR.update() : subGR.insert();
      if (subRes) {
        subGR.get(subRes);
        data.submitted = true;
        data.appNo = subGR.getValue('app_no');
      } else {
        data.submitted = false;
        data.errorMessage = "Unable to process application submission.";
      }
    } catch (eSub) {
      data.submitted = false;
      data.errorMessage = eSub.message;
    }
  }
})();
